-- Corrige le contenu des sections 1 a 5 de la Direction Logistique (groupe 5) :
-- S01 dupliquait par erreur les parties prenantes de la DSI, S03/S04 contenaient
-- des donnees de test a un mot avec encodage casse, S02/S05 etaient marquees
-- 'Soumis' sans aucun contenu enregistre. Reecrit avec un contenu reel et coherent
-- avec S06-S17 (deja completees par la migration V7) et le style des 4 autres groupes.

INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 1, '{"rows":[{"category":"AUTRE","scope":"INTERNE","roles":"Direction Commerciale : exprime les besoins de livraison et les delais clients","expectations":"Fiabilite et respect des delais d''acheminement","adaptationStrategy":"Coordination hebdomadaire commercial-logistique","importance":"FORT","influence":"FORT","actions":"Partage du planning de tournees en temps reel"},{"category":"AUTRE","scope":"INTERNE","roles":"Direction Technique et Exploitation : fournit et entretient les vehicules et infrastructures","expectations":"Disponibilite des vehicules et des equipements de tri","adaptationStrategy":"Comite technique-logistique mensuel","importance":"FORT","influence":"MOYEN","actions":"Suivi conjoint de la maintenance du parc"},{"category":"FOURNISSEUR","scope":"EXTERNE","roles":"Fournisseurs de vehicules et de pieces detachees","expectations":"Commandes previsibles et paiements dans les delais contractuels","adaptationStrategy":"Contrats-cadres pluriannuels avec fournisseurs strategiques","importance":"FORT","influence":"MOYEN","actions":"Evaluation annuelle des fournisseurs"},{"category":"PRESTATAIRE","scope":"EXTERNE","roles":"Partenaires transporteurs et prestataires de livraison sous-traitants","expectations":"Volumes reguliers confies et tarifs de sous-traitance competitifs","adaptationStrategy":"Contrats de sous-traitance avec indicateurs de service","importance":"MOYEN","influence":"MOYEN","actions":"Audits de performance semestriels des sous-traitants"},{"category":"AUTRE","scope":"EXTERNE","roles":"Clients particuliers et entreprises (dont clientele e-commerce)","expectations":"Delais de livraison courts, fiables et suivi transparent des envois","adaptationStrategy":"Amelioration continue du suivi et de l''information sur les envois","importance":"FORT","influence":"FAIBLE","actions":"Enquetes de satisfaction sur les delais de livraison"}]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
ON DUPLICATE KEY UPDATE content_json = VALUES(content_json), version = version + 1, updated_by = VALUES(updated_by);
INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 2, '{"rows":[{"resourceKey":"CADRE_JURIDIQUE_INSTITUTIONNEL","strengths":"Contrats de transport et de sous-traitance formalises","weaknesses":"Absence de clauses de revision tarifaire liees au carburant","challenges":"Securiser juridiquement les contrats de sous-traitance logistique"},{"resourceKey":"LEADERSHIP_PILOTAGE_GOUVERNANCE","strengths":"Comite d''exploitation logistique hebdomadaire","weaknesses":"Pilotage encore peu outille (absence de tableau de bord logistique)","challenges":"Structurer un pilotage de la performance logistique"},{"resourceKey":"POSITION_CONCURRENTIELLE","strengths":"Couverture logistique nationale historique","weaknesses":"Delais d''acheminement parfois superieurs a ceux de nouveaux operateurs prives","challenges":"Reduire les delais pour rester competitif face aux nouveaux entrants"},{"resourceKey":"CAPACITES_INSTITUTIONNELLES","strengths":"Reseau de centres de tri couvrant le territoire national","weaknesses":"Sous-effectif de chauffeurs et d''agents de tri dans certaines zones","challenges":"Renforcer les effectifs logistiques la ou la demande croit"},{"resourceKey":"BUDGET_RESSOURCES_FINANCIERES","strengths":"Budget d''exploitation logistique reconduit chaque annee","weaknesses":"Budget d''investissement insuffisant pour le renouvellement du parc","challenges":"Prioriser les investissements les plus critiques pour la continuite de service"},{"resourceKey":"COMPTABILITE_GESTION_FINANCIERE","strengths":"Suivi des couts de transport par centre de tri","weaknesses":"Comptabilite analytique par tournee encore incomplete","challenges":"Affiner le suivi analytique des couts logistiques par tournee"},{"resourceKey":"SYSTEME_CONTROLE","strengths":"Controle des departs et arrivees aux centres de tri","weaknesses":"Controle limite du respect des delais en cours de tournee","challenges":"Deployer un suivi en temps reel des tournees"},{"resourceKey":"SYSTEME_INFORMATION_GESTION","strengths":"Registre de suivi des expeditions tenu regulierement","weaknesses":"Absence d''outil de planification et de suivi des tournees","challenges":"Deployer un outil de planification logistique integre"},{"resourceKey":"SUIVI_EVALUATION","strengths":"Indicateurs de volumes traites suivis mensuellement","weaknesses":"Delai moyen d''acheminement peu suivi comme indicateur de pilotage","challenges":"Instaurer un tableau de bord logistique avec indicateur de delai"},{"resourceKey":"COMMUNICATION","strengths":"Bonne communication avec les centres de tri sur les volumes","weaknesses":"Communication insuffisante avec les clients en cas de retard","challenges":"Ameliorer l''information client sur le suivi des envois"},{"resourceKey":"AUTRES_ACHATS_EXPLOITATION_TECHNIQUE_RH","strengths":"Coordination correcte avec les achats pour les pieces de vehicules","weaknesses":"Delais d''approvisionnement parfois longs pour les pieces critiques","challenges":"Constituer un stock de securite pour les pieces critiques du parc"},{"resourceKey":"COMPETENCES","strengths":"Chauffeurs et agents de tri experimentes","weaknesses":"Competences limitees en planification logistique et outils numeriques","challenges":"Former les equipes aux outils de planification et de suivi logistique"}]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
