INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 3, '{"rows":[{"axis":"POLITIQUE","threats":"Evolution des reglementations de transport routier","opportunities":"Programmes publics d''appui a la modernisation des infrastructures logistiques","actions":"Suivre les evolutions reglementaires et candidater aux programmes d''appui"},{"axis":"ECONOMIQUE","threats":"Hausse du prix du carburant et des couts de transport","opportunities":"Croissance du e-commerce generant de nouveaux volumes","actions":"Optimiser les circuits pour maitriser les couts et capter la croissance du e-commerce"},{"axis":"SOCIAL_CULTUREL","threats":"Difficulte a recruter des chauffeurs qualifies","opportunities":"Interet croissant pour les metiers de la logistique et du transport","actions":"Nouer des partenariats avec des centres de formation transport/logistique"},{"axis":"TECHNOLOGIQUE","threats":"Retard dans la digitalisation du suivi logistique face aux operateurs prives","opportunities":"Solutions de geolocalisation et de planification des tournees disponibles","actions":"Deployer un outil de planification et de suivi des tournees"},{"axis":"ENVIRONNEMENTAL","threats":"Exigences croissantes de reduction des emissions du transport routier","opportunities":"Opportunites de modernisation vers des vehicules plus sobres","actions":"Integrer des criteres environnementaux dans le renouvellement du parc"},{"axis":"LEGAL","threats":"Renforcement des normes de securite routiere et de transport de marchandises","opportunities":"Cadre reglementaire clair facilitant la mise en conformite","actions":"Assurer une veille reglementaire continue sur le transport routier"}]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
ON DUPLICATE KEY UPDATE content_json = VALUES(content_json), version = version + 1, updated_by = VALUES(updated_by);
INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 4, '{"strengths":["Reseau de centres de tri couvrant l''ensemble du territoire national","Chauffeurs et agents de tri experimentes","Couverture logistique nationale historique","Bonne coordination avec les Directions Commerciale et Technique"],"weaknesses":["Vieillissement du parc de vehicules de transport","Absence d''outil de planification et de suivi des tournees","Delais d''acheminement parfois superieurs a la concurrence","Sous-effectif de chauffeurs dans certaines zones"],"opportunities":["Croissance du e-commerce generant de nouveaux volumes de colis","Solutions de geolocalisation et de planification des tournees disponibles","Programmes publics d''appui a la modernisation des infrastructures logistiques","Partenariats possibles avec des acteurs du e-commerce et de la livraison"],"threats":["Hausse du prix du carburant et des couts de transport","Difficulte a recruter des chauffeurs qualifies","Renforcement des normes de securite routiere et environnementales","Concurrence croissante d''operateurs prives de livraison"]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
