INSERT INTO section_responses (group_id, section_id, content_json, version, updated_by)
VALUES (5, 5, '{"maximizeStrengths":"S''appuyer sur le reseau de centres de tri et l''experience des equipes pour absorber la croissance des volumes de colis.","minimizeWeaknesses":"Deployer un outil de planification des tournees et accelerer le renouvellement du parc de vehicules.","strengthsControlWeaknesses":"L''experience des chauffeurs et agents de tri permet de limiter l''impact du vieillissement du parc en attendant son renouvellement.","maximizeOpportunities":"Saisir la croissance du e-commerce et les solutions de geolocalisation disponibles pour moderniser le suivi logistique.","strengthsForOpportunities":"Utiliser le reseau de centres de tri existant pour capter plus rapidement les nouveaux volumes lies au e-commerce.","correctWeaknessesViaOpportunities":"Profiter des solutions de geolocalisation disponibles pour combler l''absence d''outil de planification des tournees.","minimizeThreats":"Optimiser les circuits et diversifier les fournisseurs de carburant et de pieces pour limiter l''impact de la hausse des couts.","strengthsReduceThreats":"La couverture nationale et l''experience des equipes limitent l''impact immediat de la concurrence des operateurs prives.","minimizeWeaknessesAndThreats":"Accelerer le renouvellement du parc et la formation des chauffeurs pour mieux resister a la pression concurrentielle et reglementaire.","opportunitiesMinimizeThreats":"La croissance du e-commerce permet de mutualiser les couts de tournees et d''attenuer la hausse du prix du carburant.","strengths":["Reseau de centres de tri couvrant l''ensemble du territoire national","Chauffeurs et agents de tri experimentes","Couverture logistique nationale historique","Bonne coordination avec les Directions Commerciale et Technique"],"weaknesses":["Vieillissement du parc de vehicules de transport","Absence d''outil de planification et de suivi des tournees","Delais d''acheminement parfois superieurs a la concurrence","Sous-effectif de chauffeurs dans certaines zones"],"opportunities":["Croissance du e-commerce generant de nouveaux volumes de colis","Solutions de geolocalisation et de planification des tournees disponibles","Programmes publics d''appui a la modernisation des infrastructures logistiques","Partenariats possibles avec des acteurs du e-commerce et de la livraison"],"threats":["Hausse du prix du carburant et des couts de transport","Difficulte a recruter des chauffeurs qualifies","Renforcement des normes de securite routiere et environnementales","Concurrence croissante d''operateurs prives de livraison"]}', 1, (SELECT id FROM users WHERE username = 'dir.logistique'))
ON DUPLICATE KEY UPDATE content_json = VALUES(content_json), version = version + 1, updated_by = VALUES(updated_by);

